GDScript Example:
```gdscript
# Vector2 from scalar
print(Vector2() == Vector2(0, 0) and Vector2(0) == Vector2(0, 0)) # prints "true"
print(Vector2(12) == Vector2(12.0, 12.0)) # prints "true"

# Vector2i from scalar
print(Vector2i() == Vector2i(0, 0) and Vector2i(0) == Vector2i(0, 0)) # prints "true"
print(Vector2i(12.5) == Vector2i(12, 12)) # prints "true"

# Vector3 from scalar
print(Vector3() == Vector3(0, 0, 0) and Vector3(0) == Vector3(0, 0, 0)) # prints "true"
print(Vector3(12) == Vector3(12.0, 12.0, 12.0)) # prints "true"

# Vector3i from scalar
print(Vector3i() == Vector3i(0, 0, 0) and Vector3i(0) == Vector3i(0, 0, 0)) # prints "true"
print(Vector3i(12.5) == Vector3i(12, 12, 12)) # prints "true"

# Vector4 from scalar
print(Vector4() == Vector4(0, 0, 0, 0) and Vector4(0) == Vector4(0, 0, 0, 0)) # prints "true"
print(Vector4(12) == Vector4(12.0, 12.0, 12.0, 12.0)) # prints "true"

# Vector4i from scalar
print(Vector4i() == Vector4i(0, 0, 0, 0) and Vector4i(0) == Vector4i(0, 0, 0, 0)) # prints "true"
print(Vector4i(12.5) == Vector4i(12, 12, 12, 12)) # prints "true"
```

C++ Example:
```c++
// Vector2 from scalar
static_assert(Vector2(0) == Vector2(0, 0));
static_assert(Vector2(12) == Vector2(12.0, 12.0));

// Vector2i from scalar
static_assert(Vector2i(0) == Vector2i(0, 0));
static_assert(Vector2i(12.5) == Vector2i(12, 12));

// Vector3 from scalar
static_assert(Vector3(0) == Vector3(0, 0, 0));
static_assert(Vector3(7) == Vector3(7.0, 7.0, 7.0));
static_assert(Vector3(3.5) == Vector3(3.5, 3.5, 3.5));

// Vector3i from scalar
static_assert(Vector3i(0) == Vector3i(0, 0, 0));
static_assert(Vector3i(8) == Vector3i(8, 8, 8));
static_assert(Vector3i(12.9) == Vector3i(12, 12, 12));

// Vector4 from scalar
static_assert(Vector4(0) == Vector4(0, 0, 0, 0));
static_assert(Vector4(1.25) == Vector4(1.25, 1.25, 1.25, 1.25));
static_assert(Vector4(-5) == Vector4(-5.0, -5.0, -5.0, -5.0));

// Vector4i from scalar
static_assert(Vector4i(0) == Vector4i(0, 0, 0, 0));
static_assert(Vector4i(9) == Vector4i(9, 9, 9, 9));
static_assert(Vector4i(-3.7) == Vector4i(-3, -3, -3, -3));
```

* Closes: https://github.com/godotengine/godot-proposals/issues/3884
